/**
 * A text part in a Gemini-style message. `thought` marks reasoning content
 * that should be hidden from the user-facing text by default.
 */
export interface TextPart {
  text: string;
  thought?: boolean;
}

/**
 * A function (tool) call part emitted by the model.
 */
export interface FunctionCallPart {
  functionCall: {
    id: string;
    name: string;
    args?: Record<string, any>;
  };
}

/**
