 * Transcript parsing utilities for Qwen Code CLI JSONL files.
 *
 * Each line in a transcript is a `ChatRecord`. This module provides the pure
 * helpers used to normalize those records — extracting text, function calls,
 * tool results, timestamps and token usage — without any MLflow dependency.
 */

import { readFileSync } from 'node:fs';
import type {
  ChatRecord,
  FunctionCallPart,
  FunctionResponsePart,
  GeminiPart,
  TextPart,
} from './types.js';

export const NANOSECONDS_PER_MS = 1e6;

/**
 * Read and parse a Qwen Code JSONL transcript file into ChatRecords.
 */
export function readTranscript(path: string): ChatRecord[] {
  const content = readFileSync(path, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as ChatRecord);
}

/**
 * Convert an ISO 8601 timestamp string to nanoseconds since the Unix epoch
 * (epoch milliseconds * 1,000,000). Returns null for null, undefined or empty
 * string input.
 */
export function parseTimestampToNs(timestamp: string | null | undefined): number | null {
  if (!timestamp) {
    return null;
  }
  const ms = new Date(timestamp).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return ms * NANOSECONDS_PER_MS;
}

/**
 * Type guard: true when the part carries a `text` property.
 */
export function isTextPart(part: GeminiPart): part is TextPart {
  return typeof part === 'object' && part !== null && 'text' in part;
}

/**
 * Type guard: true when the part carries a `functionCall` property.
 */
export function isFunctionCallPart(part: GeminiPart): part is FunctionCallPart {
  return typeof part === 'object' && part !== null && 'functionCall' in part;
}

/**
 * Type guard: true when the part carries a `functionResponse` property.
 */
export function isFunctionResponsePart(part: GeminiPart): part is FunctionResponsePart {
  return typeof part === 'object' && part !== null && 'functionResponse' in part;
}

/**
 * Extract text content from a ChatRecord's message.
 *
 * - Joins multiple text parts with a newline.
 * - Excludes parts where `thought === true` unless `includeThoughts` is true.
 * - Returns a plain string message as-is.
 * - Skips functionCall / functionResponse parts (they contribute no text).
 */
export function getMessageText(record: ChatRecord, includeThoughts = false): string {
  const message = record.message;
  if (message == null) {
    return '';
  }
  if (typeof message === 'string') {
    return message;
  }

  const parts = message.parts ?? [];
  const texts: string[] = [];
  for (const part of parts) {
    if (!isTextPart(part)) {
      continue;
    }
    if (!includeThoughts && part.thought) {
      continue;
    }
    texts.push(part.text);
  }
  return texts.join('\n');
}

/**
 * Extract all functionCall parts from a ChatRecord's message.
 * Returns an empty array for records with no message or no functionCall parts.
 */
export function getFunctionCalls(
  record: ChatRecord,
): Array<{ id: string; name: string; args?: Record<string, any> }> {
  const message = record.message;
  if (message == null || typeof message === 'string') {
    return [];
  }

  const parts = message.parts ?? [];
  const calls: Array<{ id: string; name: string; args?: Record<string, any> }> = [];
  for (const part of parts) {
    if (isFunctionCallPart(part)) {
      calls.push({
        id: part.functionCall.id,
        name: part.functionCall.name,
        args: part.functionCall.args,
      });
    }
  }
  return calls;
}

/**
 * Build a Map from `toolCallResult.callId` to the tool_result ChatRecord.
 * Only tool_result records are included.
 */
export function buildToolResultMap(records: ChatRecord[]): Map<string, ChatRecord> {
  const map = new Map<string, ChatRecord>();
  for (const record of records) {
    if (record.type === 'tool_result' && record.toolCallResult?.callId) {
      map.set(record.toolCallResult.callId, record);
    }
  }
  return map;
}

/**
 * Normalize a `resultDisplay` value to a string.
 * - Passes string values through unchanged.
 * - JSON.stringifies object values.
 * - Returns an empty string for null or undefined.
 */
export function formatResultDisplay(display: any): string {
  if (display == null) {
    return '';
  }
  if (typeof display === 'string') {
    return display;
  }
  return JSON.stringify(display);
}

/**
 * Extract tool output from a tool_result record.
 *
 * Prefers `toolCallResult.resultDisplay` (normalized via formatResultDisplay).
 * Falls back to `JSON.stringify` of the `functionResponse.response` found in the
 * message parts when resultDisplay is absent. Returns an empty string if neither
 * is available.
 */
export function getToolOutput(record: ChatRecord): string {
  const resultDisplay = record.toolCallResult?.resultDisplay;
  if (resultDisplay != null) {
    return formatResultDisplay(resultDisplay);
  }

  const message = record.message;
  if (message != null && typeof message !== 'string') {
    const parts = message.parts ?? [];
    for (const part of parts) {
      if (isFunctionResponsePart(part)) {
        return JSON.stringify(part.functionResponse.response);
      }
    }
  }
  return '';
}

/**
 * Return a slice of the records array starting at the last record whose type is
 * 'user' and continuing through the end of the array. If no user record exists,
 * the full array is returned.
 */
export function getLastTurnRecords(records: ChatRecord[]): ChatRecord[] {
  for (let i = records.length - 1; i >= 0; i--) {
    if (records[i].type === 'user') {
      return records.slice(i);
    }
  }
  return records;
}

/**
 * Extract token counts from a usageMetadata object.
 * Maps promptTokenCount -> input, candidatesTokenCount -> output,
 * totalTokenCount -> total. Returns null for undefined/missing input.
 */
export function getTokenUsage(
  usageMetadata: any,
): { input: number; output: number; total: number } | null {
  if (usageMetadata == null) {
    return null;
  }
  return {
    input: usageMetadata.promptTokenCount,
    output: usageMetadata.candidatesTokenCount,
    total: usageMetadata.totalTokenCount,
  };
}
