,CAAC;IACH,CAAC;IAED,QAAQ,CAAC,GAAG,CAAC;QACX,OAAO,EAAE,aAAa,CAAC,CAAC,CAAC,IAAA,8BAAc,EAAC,aAAa,CAAC,CAAC,CAAC,CAAC,EAAE;QAC3D,GAAG,CAAC,SAAS,IAAI,IAAI,CAAC,CAAC,CAAC,EAAE,SAAS,EAAE,SAAS,EAAE,CAAC,CAAC,CAAC,EAAE,CAAC;KACvD,CAAC,CAAC;IAEH,MAAM,IAAA,kBAAW,GAAE,CAAC;AACtB,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/qwen-code/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing integration for Qwen Code CLI transcripts.\n *\n * `processTranscript` reads a JSONL conversation transcript and converts it into\n * an MLflow trace: an AGENT root span for the conversation, one LLM span per\n * assistant record, and one TOOL span per function call the assistant emitted.\n */\n\nimport {\n  startSpan,\n  flushTraces,\n  InMemoryTraceManager,\n  SpanStatusCode,\n  SpanType,\n  SpanAttributeKey,\n  TraceMetadataKey,\n  TokenUsageKey,\n  type LiveSpan,\n} from '@mlflow/core';\n\nimport type { ChatRecord, OpenAIMessage } from './types.js';\nimport {\n  parseTimestampToNs,\n  getMessageText,\n  getFunctionCalls,\n  getToolOutput,\n  getTokenUsage,\n  buildToolResultMap,\n  readTranscript,\n} from './transcript.js';\n\n/**\n * Reconstruct OpenAI chat-format message history from the records preceding\n * `targetIndex`. Used to populate LLM span inputs so the MLflow Chat view shows\n * the full conversation context that led up to each assistant call.\n *\n * - user records          -> { role: 'user', content }\n * - assistant (text only)  -> { role: 'assistant', content }  (thoughts excluded)\n * - assistant (functionCall)-> { role: 'assistant', content: null, tool_calls }\n * - tool_result records     -> { role: 'tool', tool_call_id, content }\n * - system (with message)   -> { role: 'system', content }\n * - system (no message)     -> excluded\n */\nexport function reconstructMessages(records: ChatRecord[], targetIndex: number): OpenAIMessage[] {\n  const messages: OpenAIMessage[] = [];\n\n  for (let i = 0; i < targetIndex; i++) {\n    const record = records[i];\n\n    if (record.type === 'user') {\n      messages.push({ role: 'user', content: getMessageText(record) });\n    } else if (record.type === 'assistant') {\n      const functionCalls = getFunctionCalls(record);\n      if (functionCalls.length > 0) {\n        messages.push({\n          role: 'assistant',\n          content: null,\n          tool_calls: functionCalls.map((fc) => ({\n            id: fc.id,\n            type: 'function',\n            function: {\n              name: fc.name,\n              arguments: JSON.stringify(fc.args ?? {}),\n            },\n          })),\n        });\n      } else {\n        messages.push({ role: 'assistant', content: getMessageText(record) });\n      }\n    } else if (record.type === 'tool_result') {\n      messages.push({\n        role: 'tool',\n        tool_call_id: record.toolCallResult?.callId ?? '',\n        content: getToolOutput(record),\n      });\n    } else if (record.type === 'system') {\n      if (record.message != null) {\n        messages.push({ role: 'system', content: getMessageText(record) });\n      }\n    }\n  }\n\n  return messages;\n}\n\n/**\n * Read a JSONL conversation transcript and convert it into MLflow spans.\n *\n * When `transcriptPath` is null, returns immediately without creating any spans\n * or calling flushTraces.\n */\nexport async function processTranscript(\n  transcriptPath: string | null,\n  sessionId?: string,\n): Promise<void> {\n  if (transcriptPath == null) {\n    return;\n  }\n\n  const records = readTranscript(transcriptPath);\n\n  const firstUser = records.find((r) => r.type === 'user');\n  const assistantRecords = records.filter((r) => r.type === 'assistant');\n  const lastAssistant = assistantRecords[assistantRecords.length - 1];\n\n  const rootStartNs = firstUser ? parseTimestampToNs(firstUser.timestamp) : null;\n  const rootEndNs = lastAssistant ? parseTimestampToNs(lastAssistant.timestamp) : null;\n\n  // Root AGENT span. The user prompt is passed as a raw string so MLflow can\n  // auto-generate the request preview and render the session view cleanly.\n  const rootSpan = startSpan({\n    name: 'qwen_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: firstUser ? getMessageText(firstUser) : '',\n    ...(rootStartNs != null ? { startTimeNs: rootStartNs } : {}),\n  });\n\n  const toolResultMap = buildToolResultMap(records);\n\n  for (let i = 0; i < records.length; i++) {\n    const record = records[i];\n    if (record.type !== 'assistant') {\n      continue;\n    }\n\n    const recordNs = parseTimestampToNs(record.timestamp);\n    const prevNs = i > 0 ? parseTimestampToNs(records[i - 1].timestamp) : null;\n    const model = record.model ?? 'unknown';\n\n    // LLM span covers the API call that produced this assistant record. Its\n    // input is the full reconstructed chat history in OpenAI request format.\n    const llmSpan = startSpan({\n      name: 'llm_call',\n      parent: rootSpan,\n      spanType: SpanType.LLM,\n      startTimeNs: prevNs ?? recordNs ?? undefined,\n      inputs: {\n        model,\n        messages: reconstructMessages(records, i),\n      },\n    });\n\n    const usage = getTokenUsage(record.usageMetadata);\n    if (usage) {\n      llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n        [TokenUsageKey.INPUT_TOKENS]: usage.input,\n        [TokenUsageKey.OUTPUT_TOKENS]: usage.output,\n        [TokenUsageKey.TOTAL_TOKENS]: usage.total,\n      });\n    }\n\n    llmSpan.end({\n      outputs: {\n        choices: [{ message: { role: 'assistant', content: getMessageText(record) } }],\n      },\n      ...(recordNs != null ? { endTimeNs: recordNs } : {}),\n    });\n\n    // One TOOL span per functionCall part within this assistant record.\n    for (const fc of getFunctionCalls(record)) {\n      const matching = toolResultMap.get(fc.id);\n      const toolEndNs = matching ? parseTimestampToNs(matching.timestamp) : null;\n\n      const toolSpan = startSpan({\n        name: `tool_${fc.name}`,\n        parent: rootSpan,\n        spanType: SpanType.TOOL,\n        startTimeNs: recordNs ?? undefined,\n        inputs: fc.args ?? {},\n        attributes: { tool_id: fc.id },\n      });\n\n      // A cancelled tool call is surfaced as an ERROR status in the trace UI.\n      // Successful calls keep the default (unset/OK) status.\n      if (matching?.toolCallResult?.status === 'cancelled') {\n        toolSpan.setStatus(SpanStatusCode.ERROR, `Tool call ${fc.name} was cancelled`);\n      }\n\n      toolSpan.end({\n        outputs: { result: matching ? getToolOutput(matching) : '' },\n        ...(toolEndNs != null ? { endTimeNs: toolEndNs } : recordNs != null ? { endTimeNs: recordNs } : {}),\n      });\n    }\n  }\n\n  // Aggregate token usage on the root span. input_tokens is the prompt size of\n  // the LAST assistant call (the full context window), while output_tokens sums\n  // the generated tokens across every assistant call in the conversation.\n  if (assistantRecords.length > 0) {\n    const inputTokens = lastAssistant?.usageMetadata?.promptTokenCount ?? 0;\n    const outputTokens = assistantRecords.reduce(\n      (sum, r) => sum + (r.usageMetadata?.candidatesTokenCount ?? 0),\n      0,\n    );\n    rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n      [TokenUsageKey.INPUT_TOKENS]: inputTokens,\n      [TokenUsageKey.OUTPUT_TOKENS]: outputTokens,\n      [TokenUsageKey.TOTAL_TOKENS]: inputTokens + outputTokens,\n    });\n  }\n\n  // Attach session/user metadata directly on the trace. We use\n  // InMemoryTraceManager because `updateCurrentTrace()` requires an active OTel\n  // span context, which this transcript-driven flow does not establish.\n  const traceId = rootSpan.traceId;\n  if (traceId) {\n    const traceManager = InMemoryTraceManager.getInstance();\n    const trace = traceManager.getTrace(traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        [TraceMetadataKey.TRACE_SESSION]: sessionId ?? firstUser?.sessionId ?? records[0]?.sessionId ?? '',\n        [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',\n      };\n    }\n  }\n\n  rootSpan.end({\n    outputs: lastAssistant ? getMessageText(lastAssistant) : '',\n    ...(rootEndNs != null ? { endTimeNs: rootEndNs } : {}),\n  });\n\n  await flushTraces();\n}\n"],"version":3}
